/// A component entry (form) with sub-entries.
///
/// Describes a single external or standard component planned for use:
/// vendor assessment, maturity, security, cost, deployment model, licensing,
/// interfaces, and responsibilities.
pub struct ComponentEntry {
    pub node: som::SomNode,
}

impl ComponentEntry {
    /// Binds a ComponentEntry facade to a document and a path.
    pub fn new(doc: som::DocRef, path: String) -> ComponentEntry {
        ComponentEntry { node: som::SomNode::new(doc, path) }
    }

    pub fn content(&self) -> ComponentEntryContentForm {
        ComponentEntryContentForm::new(self.node.doc(), format!("{}/{}", self.node.path(), "content"))
    }

    /// Vendor information.
    pub fn vendor(&self) -> ComponentVendor {
        ComponentVendor::new(self.node.doc(), format!("{}/{}", self.node.path(), "vendor"))
    }

    /// Maturity and community.
    pub fn maturity(&self) -> ComponentMaturity {
        ComponentMaturity::new(self.node.doc(), format!("{}/{}", self.node.path(), "maturity"))
    }

    /// Support.
    pub fn support(&self) -> ComponentSupport {
        ComponentSupport::new(self.node.doc(), format!("{}/{}", self.node.path(), "support"))
    }

    /// Security and performance.
    pub fn performance(&self) -> ComponentPerformance {
        ComponentPerformance::new(self.node.doc(), format!("{}/{}", self.node.path(), "performance"))
    }

    /// Deployment.
    pub fn deployment(&self) -> ComponentDeployment {
        ComponentDeployment::new(self.node.doc(), format!("{}/{}", self.node.path(), "deployment"))
    }

    /// Cost.
    pub fn cost(&self) -> ComponentCost {
        ComponentCost::new(self.node.doc(), format!("{}/{}", self.node.path(), "cost"))
    }

    /// Compliance and training.
    pub fn compliance(&self) -> ComponentCompliance {
        ComponentCompliance::new(self.node.doc(), format!("{}/{}", self.node.path(), "compliance"))
    }

    /// Risk assessment.
    pub fn risk(&self) -> ComponentRisk {
        ComponentRisk::new(self.node.doc(), format!("{}/{}", self.node.path(), "risk"))
    }

    /// Documentation.
    pub fn docs(&self) -> som::SomList<ComponentDocs> {
        som::SomList::new(
            self.node.doc(),
            format!("{}/{}", self.node.path(), "CODO-DOCS-LST"),
            Box::new(|d, p| ComponentDocs::new(d, p)),
        )
    }

    /// Interfaces — contains 0+× ComponentInterface.
    pub fn interfaces(&self) -> som::SomList<ComponentInterfaceEntry> {
        som::SomList::new(
            self.node.doc(),
            format!("{}/{}", self.node.path(), "CMIF-INTE-LST"),
            Box::new(|d, p| ComponentInterfaceEntry::new(d, p)),
        )
    }

    /// Licensing (form).
    pub fn licensing(&self) -> ComponentLicensingEntry {
        ComponentLicensingEntry::new(self.node.doc(), format!("{}/{}", self.node.path(), "licensing"))
    }

    // Usage Rights.
    // (skipped: usageRights has no target type)

    /// Responsibilities (form).
    pub fn responsibilities(&self) -> som::SomList<ComponentResponsibilitiesEntry> {
        som::SomList::new(
            self.node.doc(),
            format!("{}/{}", self.node.path(), "COREEN-RESP-LST"),
            Box::new(|d, p| ComponentResponsibilitiesEntry::new(d, p)),
        )
    }
}

