/// A risk entry (form).
///
/// Comprehensive risk documentation following ISO 31000 and PMBOK guidelines.
/// Captures risk identification, analysis, response planning, ownership,
/// and monitoring information for systematic risk management.
pub struct RiskEntry {
    pub node: som::SomNode,
}

impl RiskEntry {
    /// Binds a RiskEntry facade to a document and a path.
    pub fn new(doc: som::DocRef, path: String) -> RiskEntry {
        RiskEntry { node: som::SomNode::new(doc, path) }
    }

    /// Risk identification — unique identifier and basic description.
    pub fn identification(&self) -> RiskIdentification {
        RiskIdentification::new(self.node.doc(), format!("{}/{}", self.node.path(), "identification"))
    }

    /// Risk analysis — probability, impact, and scoring.
    pub fn analysis(&self) -> RiskAnalysis {
        RiskAnalysis::new(self.node.doc(), format!("{}/{}", self.node.path(), "analysis"))
    }

    /// Risk response — strategy and planned actions.
    pub fn response(&self) -> RiskResponse {
        RiskResponse::new(self.node.doc(), format!("{}/{}", self.node.path(), "response"))
    }

    /// Risk ownership and governance.
    pub fn ownership(&self) -> RiskOwnership {
        RiskOwnership::new(self.node.doc(), format!("{}/{}", self.node.path(), "ownership"))
    }

    /// Risk monitoring and tracking details.
    pub fn monitoring(&self) -> RiskMonitoring {
        RiskMonitoring::new(self.node.doc(), format!("{}/{}", self.node.path(), "monitoring"))
    }

    /// Business impact assessment.
    pub fn business_impact(&self) -> RiskBusinessImpact {
        RiskBusinessImpact::new(self.node.doc(), format!("{}/{}", self.node.path(), "businessImpact"))
    }

    /// Relationships to other risks, assumptions, and project elements.
    pub fn relationships(&self) -> som::SomList<RiskRelationships> {
        som::SomList::new(
            self.node.doc(),
            format!("{}/{}", self.node.path(), "RR-RELA-LST"),
            Box::new(|d, p| RiskRelationships::new(d, p)),
        )
    }
}

